     1	#!/usr/bin/env node
     2	// Derives the ephemeral MRT preview target slug for a branch name. Shared by
     3	// deploy-preview.yml and teardown-preview.yml so both compute the identical slug
     4	// for a given branch — teardown must find exactly what deploy created, and two
     5	// independently-maintained copies of this logic would eventually drift.
     6	//
     7	// Usage: node scripts/computeMrtPreviewSlug.mjs '<branch-name>'
     8	// Prints the slug to stdout on success. Exits 1 with a message on stderr if no
     9	// valid, non-empty slug can be derived.
    10	
    11	import { createHash } from 'node:crypto';
    12	
    13	// Hard MRT API limit, confirmed live: POSTing a longer name 400s with
    14	// {"slug":"Target names can be at most 19 characters."} — not a DNS-label
    15	// assumption, an actual enforced constraint. This leaves very little room, so
    16	// every character below is deliberately budgeted.
    17	const MAX_SLUG_LEN = 19;
    18	const PREFIX = 'pr-'; // required — this is what makes collision with the fixed
    19	// named tiers (dev, test, sit, uat, stg, production, dev1) structurally
    20	// impossible, so it isn't a place to economize further.
    21	
    22	// A digest of the full, untransformed branch name is appended to every slug,
    23	// not just ones long enough to need truncating — the readable part alone is a
    24	// lossy normalization (punctuation collapses, the Jira key is stripped from
    25	// wherever it appears, and there's barely any room for it besides) and can
    26	// collide for distinct branch names, e.g. `feature/checkout-header` and
    27	// `feature/checkout_header`. The digest is what makes collisions between
    28	// distinct branch names astronomically unlikely — not impossible, since it's
    29	// a hash, not a reversible encoding — while the readable part is purely for
    30	// browsing Runtime Admin. Accepted residual risk: a true collision would need
    31	// two distinct branch names to share the same digest, which no realistic
    32	// number of concurrent preview branches will ever approach. 8 hex chars (32
    33	// bits) is the most this 19-char budget can spare it while still leaving room
    34	// for anything human-readable at all.
    35	const HASH_LEN = 8;
    36	const STEM_LEN = MAX_SLUG_LEN - PREFIX.length - HASH_LEN - 1; // -1 for the hyphen before the hash
    37	
    38	const branch = process.argv[2];
    39	
    40	const die = (msg) => {
    41	  console.error(`✗ computeMrtPreviewSlug: ${msg}`);
    42	  process.exit(1);
    43	};
    44	
    45	if (!branch) die('usage: computeMrtPreviewSlug.mjs <branch-name>');
    46	
    47	const jiraMatch = branch.match(/SFCC-(\d+)/i);
    48	
    49	// A single-char kind marker (not "ft"/"fx" — no room to spare) is still
    50	// enough to keep feature/SFCC-123-x and fix/SFCC-123-x from colliding on the
    51	// readable part, which otherwise strips the feature/fix prefix entirely.
    52	const prefixMatch = branch.match(/^(feature|fix)\//);
    53	const kind = prefixMatch ? (prefixMatch[1] === 'feature' ? 'f' : 'x') : '';
    54	
    55	const withoutPrefix = branch.replace(/^(feature|fix)\//, '').replace(/SFCC-\d+/i, '');
    56	const sanitized = withoutPrefix
    57	  .toLowerCase()
    58	  .replace(/[^a-z0-9]+/g, '-')
    59	  .replace(/-+/g, '-')
    60	  .replace(/^-|-$/g, '');
    61	
    62	// Prefer the Jira ticket number over the free-text remainder when both are
    63	// present — it's the more useful thing to recognize at a glance with only a
    64	// handful of characters to spend, and this repo's branch convention always
    65	// carries one when a story exists.
    66	let content;
    67	if (jiraMatch) {
    68	  content = jiraMatch[1];
    69	} else {
    70	  if (!sanitized) die(`branch "${branch}" sanitizes to an empty slug — refusing to proceed`);
    71	  content = sanitized;
    72	}
    73	
    74	const stem = `${kind}${content}`.slice(0, STEM_LEN).replace(/^-|-$/g, '');
    75	const hash = createHash('sha256').update(branch).digest('hex').slice(0, HASH_LEN);
    76	
    77	console.log(`${PREFIX}${stem}-${hash}`);

